insert into sys_merchant_notice_read (merchant_notice_id, member_id, merchant_user_id, read_time, is_delete) select n.merchant_notice_id, #{memberId}, #{merchantUserId}, sysdate(), 0 from sys_merchant_notice n where n.status = 0 and n.is_delete = 0 and n.merchant_notice_id in
#{noticeId}
and (n.target_scope = 1 or exists ( select 1 from sys_merchant_notice_member tm where tm.merchant_notice_id = n.merchant_notice_id and tm.member_id = #{memberId} and tm.is_delete = 0 )) on duplicate key update read_time = values(read_time), is_delete = 0
